import { test, expect } from '@playwright/test';

test.describe('Active Filter Tags Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display tag for single active filter above results', async ({ page }) => {
    // Apply a filter
    const filterButton = page.getByRole('button', { name: /filter/i });
    await filterButton.click();

    const categoryFilter = page.getByLabel(/category/i);
    await categoryFilter.click();

    const categoryOption = page.getByRole('option', { name: /electronics/i });
    await categoryOption.click();

    // Verify filter tag appears above results
    const filterTag = page.getByRole('button', { name: /electronics/i });
    await expect(filterTag).toBeVisible();

    // Verify results are displayed below the tag
    const resultsList = page.getByRole('list', { name: /results/i });
    await expect(resultsList).toBeVisible();

    const filterTagBox = await filterTag.boundingBox();
    const resultsBox = await resultsList.boundingBox();

    if (filterTagBox && resultsBox) {
      expect(filterTagBox.y).toBeLessThan(resultsBox.y);
    }
  });

  test('should display multiple tags for multiple active filters', async ({ page }) => {
    // Apply first filter
    const filterButton = page.getByRole('button', { name: /filter/i });
    await filterButton.click();

    const categoryFilter = page.getByLabel(/category/i);
    await categoryFilter.click();

    const categoryOption = page.getByRole('option', { name: /electronics/i });
    await categoryOption.click();

    // Apply second filter
    const priceFilter = page.getByLabel(/price/i);
    await priceFilter.click();

    const priceOption = page.getByRole('option', { name: /under \$100/i });
    await priceOption.click();

    // Verify both filter tags appear
    const electronicsTag = page.getByRole('button', { name: /electronics/i });
    const priceTag = page.getByRole('button', { name: /under \$100/i });

    await expect(electronicsTag).toBeVisible();
    await expect(priceTag).toBeVisible();

    // Verify tags are positioned above results
    const resultsList = page.getByRole('list', { name: /results/i });
    await expect(resultsList).toBeVisible();

    const electronicsBox = await electronicsTag.boundingBox();
    const priceBox = await priceTag.boundingBox();
    const resultsBox = await resultsList.boundingBox();

    if (electronicsBox && priceBox && resultsBox) {
      expect(electronicsBox.y).toBeLessThan(resultsBox.y);
      expect(priceBox.y).toBeLessThan(resultsBox.y);
    }
  });

  test('should remove filter when clicking remove button on tag', async ({ page }) => {
    // Apply a filter
    const filterButton = page.getByRole('button', { name: /filter/i });
    await filterButton.click();

    const categoryFilter = page.getByLabel(/category/i);
    await categoryFilter.click();

    const categoryOption = page.getByRole('option', { name: /electronics/i });
    await categoryOption.click();

    // Verify filter tag appears
    const filterTag = page.getByRole('button', { name: /electronics/i });
    await expect(filterTag).toBeVisible();

    // Click remove button on tag
    const removeButton = filterTag.getByRole('button', { name: /remove|close|x/i });
    await removeButton.click();

    // Verify filter tag is removed
    await expect(filterTag).not.toBeVisible();
  });

  test('should display filter tags in correct order', async ({ page }) => {
    // Apply multiple filters in sequence
    const filterButton = page.getByRole('button', { name: /filter/i });
    await filterButton.click();

    const categoryFilter = page.getByLabel(/category/i);
    await categoryFilter.click();

    const categoryOption = page.getByRole('option', { name: /electronics/i });
    await categoryOption.click();

    const priceFilter = page.getByLabel(/price/i);
    await priceFilter.click();

    const priceOption = page.getByRole('option', { name: /under \$100/i });
    await priceOption.click();

    const brandFilter = page.getByLabel(/brand/i);
    await brandFilter.click();

    const brandOption = page.getByRole('option', { name: /samsung/i });
    await brandOption.click();

    // Get all filter tags
    const filterTags = page.locator('[data-testid="filter-tag"]');
    const tagCount = await filterTags.count();

    expect(tagCount).toBe(3);

    // Verify tags are displayed in a container above results
    const filterContainer = page.getByRole('region', { name: /active filters/i });
    await expect(filterContainer).toBeVisible();

    const resultsList = page.getByRole('list', { name: /results/i });
    const containerBox = await filterContainer.boundingBox();
    const resultsBox = await resultsList.boundingBox();

    if (containerBox && resultsBox) {
      expect(containerBox.y).toBeLessThan(resultsBox.y);
    }
  });

  test('should update results when filter tag is removed', async ({ page }) => {
    // Get initial result count
    const filterButton = page.getByRole('button', { name: /filter/i });
    await filterButton.click();

    const categoryFilter = page.getByLabel(/category/i);
    await categoryFilter.click();

    const categoryOption = page.getByRole('option', { name: /electronics/i });
    await categoryOption.click();

    const initialResults = page.getByRole('listitem');
    const initialCount = await initialResults.count();

    // Remove the filter
    const filterTag = page.getByRole('button', { name: /electronics/i });
    const removeButton = filterTag.getByRole('button', { name: /remove|close|x/i });
    await removeButton.click();

    // Wait for results to update
    await page.waitForTimeout(500);

    // Verify result count changed
    const updatedResults = page.getByRole('listitem');
    const updatedCount = await updatedResults.count();

    expect(updatedCount).not.toBe(initialCount);
  });
});
